def execute_command(image) -> ImagePatch:
    image_patch = ImagePatch(image)
    people = image_patch.find("person")
    benches = image_patch.find("bench")

    if not people or not benches:
        return image_patch

    people.sort(key=lambda p: p.horizontal_center)
    left_people = people[:max(1, len(people) // 2)]

    best_person = None
    min_distance = float('inf')

    for person in left_people:
        for bench in benches:
            if person.horizontal_center < bench.horizontal_center:
                distance_to_bench = distance(person, bench)
                if distance_to_bench < min_distance:
                    min_distance = distance_to_bench
                    best_person = person

    return best_person

