def execute_command(image) -> ImagePatch:
    image_patch = ImagePatch(image)
    baby_patches = image_patch.find("baby")
    toy_patches = image_patch.find("toy")

    if not baby_patches or not toy_patches:
        return image_patch

    baby_centers = [(p.left + p.right) / 2 for p in baby_patches]
    toy_centers = [(p.left + p.right) / 2 for p in toy_patches]

    baby_toy_pairs = []
    for baby_idx, baby_center in enumerate(baby_centers):
        for toy_idx, toy_center in enumerate(toy_centers):
            if abs(baby_center - toy_center) < min(abs(baby_left - baby_right), abs(toy_left - toy_right)) / 2:
                baby_toy_pairs.append((baby_idx, toy_idx))

    if not baby_toy_pairs:
        return image_patch

    baby_toy_distances = [distance_3d(baby_patches[baby_idx], toy_patches[toy_idx]) for baby_idx, toy_idx in baby_toy_pairs]
    closest_pair = baby_toy_pairs[baby_toy_distances.index(min(baby_toy_distances))]

    return baby_patches[closest_pair[0]]

